BASE_URL = "https://en.wikipedia.org"
DEFAULT_HEADERS = {
    "User-Agent": "Mozilla/5.0 (compatible; wiki_python-mcp/1.0)",
    "Accept": "text/html,application/xhtml+xml,*/*",
}

@mcp.tool(name="search_wikipedia")
def search_wikipedia(
    search: str | None = "",
    title: str | None = 'Special:Search',
) -> str:
    """Search for Wikipedia articles or retrieve a specific article by its exact title. Use this tool to find information across the entire encyclopedia or navigate to a known article.
    Args:
        search: Keywords to search for within Wikipedia articles.
        title: Exact title of a Wikipedia article to retrieve directly without searching.
    Returns:
        Contenu textuel extrait de la page /w/index.php
    """
    url = BASE_URL.rstrip("/") + "/w/index.php"
    # Les paramètres optionnels non fournis (None, ou chaîne vide pour un
    # champ de formulaire texte) ne doivent pas partir dans la query string
    # — un paramètre vide explicite (ex: `search=`) peut changer le
    # comportement de l'endpoint cible (ex: devenir une recherche vide au
    # lieu d'aucune recherche), contrairement à son absence pure et simple.
    _raw_params = { "search": search, "title": title }
    _params = {k: v for k, v in _raw_params.items() if v is not None and v != ""}
    try:
        with httpx.Client(headers=DEFAULT_HEADERS, follow_redirects=True, timeout=30) as client:
            response = client.get(
                url,
                params=_params,
            )
        if not response.is_success:
            return f"HTTP {response.status_code}: {response.text[:500]}"
        soup = BeautifulSoup(response.text, "html.parser")
        for tag in soup(["script", "style", "nav", "footer"]):
            tag.decompose()
        return soup.get_text(separator="\n", strip=True)
    except httpx.TimeoutException:
        return "Error: request timed out after 30s"
    except httpx.RequestError as exc:
        return f"Error: network error — {exc}"

